const body = $json.body ?? $json;

const contractVersion = String(body.contractVersion ?? '');
const requestId = String(body.requestId ?? `REQ-${Date.now()}`);
const projectId = String(body.projectId ?? '');
const userStories = Array.isArray(body.userStories) ? body.userStories : [];

if (contractVersion !== 'v1') {
  throw new Error(`Unsupported contractVersion: ${contractVersion}`);
}
if (!projectId) {
  throw new Error('Missing projectId');
}
if (userStories.length === 0) {
  throw new Error('No userStories provided');
}

return [{
  json: {
    contractVersion,
    requestId,
    projectId,
    userStories: userStories.map((s) => ({
      id: String(s?.id ?? ''),
      title: String(s?.title ?? ''),
      description: String(s?.description ?? ''),
      module: String(s?.module ?? 'General'),
      criteria: Array.isArray(s?.criteria) ? s.criteria.map((c) => String(c)) : []
    })).filter((s) => s.id && s.title)
  }
}];

function safeParse(value) {
  if (typeof value !== 'string') return null;
  try { return JSON.parse(value); } catch { return null; }
}

const raw = $json.text ?? $json.response ?? $json.output ?? JSON.stringify($json);
const parsed = typeof raw === 'string' ? safeParse(raw) : raw;

if (!parsed || typeof parsed !== 'object') {
  throw new Error('Model did not return valid JSON');
}
if (!Array.isArray(parsed.testCases)) {
  throw new Error('JSON does not contain testCases[]');
}

const allowedTypes = new Set(['functional', 'negative', 'edge', 'integration', 'performance', 'security']);
const allowedPriorities = new Set(['high', 'medium', 'low']);
const allowedStatus = new Set(['generated', 'pending', 'review']);

const testCases = parsed.testCases
  .filter((tc) => tc && typeof tc === 'object')
  .map((tc) => {
    const t = tc;
    const type = String(t.type ?? 'functional').toLowerCase();
    const priority = String(t.priority ?? 'medium').toLowerCase();
    const status = String(t.status ?? 'generated').toLowerCase();
    return {
      storyId: String(t.storyId ?? '').trim(),
      description: String(t.description ?? '').trim(),
      preconditions: String(t.preconditions ?? '').trim(),
      steps: String(t.steps ?? '').trim(),
      expected: String(t.expected ?? '').trim(),
      type: allowedTypes.has(type) ? type : 'functional',
      priority: allowedPriorities.has(priority) ? priority : 'medium',
      status: allowedStatus.has(status) ? status : 'generated'
    };
  })
  .filter((tc) => tc.storyId && tc.description);

if (testCases.length === 0) {
  throw new Error('No valid test cases produced');
}

return [{
  json: {
    runId: String(parsed.runId ?? `RUN-${Date.now()}`),
    requestId: String(parsed.requestId ?? ''),
    projectId: String(parsed.projectId ?? ''),
    testCases
  }
}];
